with lines as (select id, service, host, log_ts, level, status_code, key, attr_value from app_logs lateral view outer explode(context) x as key, attr_value), unpacked as (select id, log_ts, key, attr_value, cast((status_code & 8) != 0 as int) as flag_bit8, shiftright(status_code, 2) as status_code_high from lines), cleaned as (select *, flag_bit8 * status_code_high as flag_bit8_times_status_code_high, coalesce(key, 'OTHER') as resolved_key from unpacked where log_ts >= to_timestamp('2025-06-01 14:00:00') and key is not null), valid as (select *, round(flag_bit8_times_status_code_high, 2) as flag_bit8_times_status_code_high_rounded, greatest(flag_bit8, status_code_high) as greatest_flag_bit8_status_code_high from cleaned where key is not null) select id, log_ts, attr_value, status_code_high, flag_bit8_times_status_code_high, resolved_key, flag_bit8_times_status_code_high_rounded from valid
